import{_ as e,c as t,o as a,a2 as o}from"./chunks/framework.DdOM6S6U.js";const b=JSON.parse('{"title":"Activators","description":"","frontmatter":{"sidebarPos":1,"sidebarTitle":"Overview","sidebarGroupTitle":"Activators"},"headers":[],"relativePath":"system-reference/backend/activators/overview.md","filePath":"system-reference/backend/activators/overview.md","lastUpdated":1778363927000}'),s={name:"system-reference/backend/activators/overview.md"},r=o('<h1 id="activators" tabindex="-1">Activators <a class="header-anchor" href="#activators" aria-label="Permalink to &quot;Activators&quot;">​</a></h1><p><strong>Directory</strong>: <code>src/Activators/</code><br><strong>Namespace</strong>: <code>Unusualify\\Modularous\\Activators</code></p><p>Activators persist and resolve enable/disable state. Modularous uses two activator layers:</p><ul><li><strong>Module activator</strong> (<code>ModularousActivator</code>) controls whether a module is enabled at all.</li><li><strong>Route activator</strong> (<code>ModuleActivator</code>) controls whether specific route actions inside a module are enabled.</li></ul><h2 id="classes" tabindex="-1">Classes <a class="header-anchor" href="#classes" aria-label="Permalink to &quot;Classes&quot;">​</a></h2><table><thead><tr><th>Class</th><th>Purpose</th><th>Page</th></tr></thead><tbody><tr><td><code>ModularousActivator</code></td><td>Stores and resolves module-level statuses (<code>enabled</code> / <code>disabled</code>) via JSON + cache</td><td><a href="./modularous-activator">ModularousActivator →</a></td></tr><tr><td><code>ModuleActivator</code></td><td>Stores and resolves route-level statuses per module (<code>routes_statuses.json</code>)</td><td><a href="./module-activator">ModuleActivator →</a></td></tr></tbody></table><h2 id="activation-model" tabindex="-1">Activation Model <a class="header-anchor" href="#activation-model" aria-label="Permalink to &quot;Activation Model&quot;">​</a></h2><ol><li>A module is discovered and checked by <strong>module-level</strong> status.</li><li>If module-level status allows it, routes are checked by <strong>route-level</strong> status.</li><li>Route enable/disable commands update route statuses without fully disabling the module.</li></ol><p>This makes it possible to keep a module active while disabling selected route actions.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/system-reference/modules">Module System</a> — high-level module lifecycle and route actions</li><li><a href="/guide/console/module/route-enable">Commands · route:enable</a></li><li><a href="/guide/console/module/route-disable">Commands · route:disable</a></li></ul>',11),l=[r];function d(i,c,n,u,h,v){return a(),t("div",null,l)}const _=e(s,[["render",d]]);export{b as __pageData,_ as default};
